import {generations, books, procedures, parts, buildPaths, streetBuildOptions, diagnosticTrees, performanceUpgradeOptions} from './content.js';
import {createGarageStore} from './garage-store.js';
import {generationManuals} from './generation-content.js';

const STORAGE_KEY='miataBibleRebuildV1';
const baseProfile={buildName:'My Miata',generation:'ND',year:2017,trim:'RF Club',mileage:40000,market:'North America'};
const store=createGarageStore(STORAGE_KEY,()=>({view:'garage',buildTab:'future',activeBook:'orientation',query:'',generationFilter:'all',profile:{...baseProfile},parts:[],history:[],plan:[],budget:3500,planName:'Reliable street build',estimateAddress:'',estimateZip:'',taxRate:8,savedProcedures:[],generationManual:'NA',dyno:{upgrades:[],weight:0,loss:15,surface:'street',driver:'average'}}));
let state=store.load();

function loadState(){
  try{
    const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||{};
    return {
      view:raw.view||'garage', buildTab:raw.buildTab||'future', activeBook:raw.activeBook||'orientation', query:raw.query||'', generationFilter:raw.generationFilter||'all',
      profile:{...baseProfile,...(raw.profile||{})}, parts:Array.isArray(raw.parts)?raw.parts:[], history:Array.isArray(raw.history)?raw.history:[],
      plan:Array.isArray(raw.plan)?raw.plan:[], budget:Number(raw.budget)||3500, planName:raw.planName||'Reliable street build', estimateAddress:raw.estimateAddress||'', estimateZip:raw.estimateZip||'', taxRate:Number(raw.taxRate)||8, savedProcedures:Array.isArray(raw.savedProcedures)?raw.savedProcedures:[], dyno:{upgrades:[],weight:0,loss:15,surface:'street',driver:'average',...(raw.dyno||{})}
    };
  }catch{return {view:'garage',buildTab:'future',activeBook:'orientation',query:'',generationFilter:'all',profile:{...baseProfile},parts:[],history:[],plan:[],budget:3500,planName:'Reliable street build',estimateAddress:'',estimateZip:'',taxRate:8,savedProcedures:[],dyno:{upgrades:[],weight:0,loss:15,surface:'street',driver:'average'}}}
}
function persist(){store.save(state);render();toast('Saved to this device · export backup or add optional sync');}
function $(selector,root=document){return root.querySelector(selector)}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function money(value){return '$'+Number(value||0).toLocaleString('en-US',{maximumFractionDigits:0})}
const catalogLinks={
  'pads-street':['https://flyinmiata.com/collections/brakes','Flyin’ Miata brake catalog'],
  'pads-track':['https://flyinmiata.com/collections/brakes','Flyin’ Miata brake catalog'],
  'coilovers':['https://949racing.com/supermiata/','949 Racing SuperMiata'],
  'tires-200tw':['https://www.tirerack.com/tires/types/200tw-summer-tires','Tire Rack 200TW category'],
  'sway-bar':['https://flyinmiata.com/collections/suspension','Flyin’ Miata suspension catalog'],
  'cooling-refresh':['https://flyinmiata.com/collections/cooling','Flyin’ Miata cooling catalog'],
  'oil-cooler':['https://flyinmiata.com/collections/oil-cooling','Flyin’ Miata oil cooling'],
  'roll-bar':['https://bethania-garage.com/','Bethania Garage'],
  'clutch-flywheel-na-nb':['https://flyinmiata.com/collections/clutch-flywheel','Flyin’ Miata clutch/flywheel'],
  'clutch-flywheel-nc':['https://flyinmiata.com/collections/clutch-flywheel','Flyin’ Miata clutch/flywheel'],
  'clutch-flywheel-nd':['https://flyinmiata.com/collections/clutch-flywheel','Flyin’ Miata clutch/flywheel'],
  'alignment-four-wheel':['https://949racing.com/supermiata/tech-info/miata-race-alignment-info/','949 Racing alignment reference'],
  'brake-fluid-high-temp':['https://motul.com/en-US/products/rbf-600-factory-line','Motul RBF 600'],
  'corner-balance':['https://949racing.com/supermiata/','949 Racing SuperMiata']
};
function catalogLink(id){const x=catalogLinks[id];return x?`<a class="product-link" href="${x[0]}" target="_blank" rel="noopener noreferrer">${x[1]} ↗</a>`:''}
const laborGuide={
  'perf-tires':'DIY 2–4 hr · shop 1–2 hr · $120–$300',
  'perf-dampers':'DIY 10–18 hr · shop 6–10 hr · $750–$1,500',
  'perf-sway':'DIY 4–8 hr · shop 2–4 hr · $250–$600',
  'perf-brake-pads':'DIY 3–6 hr · shop 2–4 hr · $180–$500',
  'perf-fluid':'DIY 1–3 hr · shop 1–2 hr · $100–$250',
  'perf-alignment':'DIY setup only · shop 1–2 hr · $150–$300',
  'perf-corner':'DIY not equivalent · shop 3–6 hr · $250–$500',
  'perf-oil-cooler':'DIY 6–12 hr · shop 4–8 hr · $500–$1,200',
  'perf-rollbar':'DIY 8–16 hr · shop 5–10 hr · $600–$1,500',
  'perf-clutch':'DIY 12–22 hr · shop 8–14 hr · $900–$2,100',
  'perf-intake-exhaust':'DIY 3–10 hr · shop 2–6 hr · $250–$900',
  'perf-forced-induction':'DIY 30–70 hr · shop 20–45 hr · $2,500–$7,500',
  'perf-data':'DIY 6–20 hr · shop 4–12 hr · $400–$1,800',
  'cooling-refresh':'DIY 4–8 hr · shop 3–6 hr · $300–$900',
  'pads-track':'DIY 3–6 hr · shop 2–4 hr · $180–$500',
  'pads-street':'DIY 3–6 hr · shop 2–4 hr · $180–$500',
  'coilovers':'DIY 10–18 hr · shop 6–10 hr · $750–$1,500',
  'clutch-flywheel-na-nb':'DIY 12–22 hr · shop 8–14 hr · $900–$2,100',
  'clutch-flywheel-nc':'DIY 14–24 hr · shop 9–16 hr · $1,100–$2,400',
  'clutch-flywheel-nd':'DIY 14–24 hr · shop 9–16 hr · $1,100–$2,400'
};
function laborFor(id){return laborGuide[id]||'DIY 2–8 hr · shop 1–4 hr · $150–$600'}
const dynoBase={NA:{hp:116,weight:2200,zero:8.5},NB:{hp:140,weight:2350,zero:7.7},NC:{hp:170,weight:2500,zero:6.8},ND:{hp:181,weight:2330,zero:6.5}};
const dynoPower={
  'perf-intake-exhaust':8,'perf-forced-induction':75,'perf-tires':0,'perf-dampers':0,'perf-sway':0,'perf-brake-pads':0,'perf-fluid':0,'perf-alignment':0,'perf-corner':0,'perf-oil-cooler':0,'perf-rollbar':0,'perf-clutch':0,'perf-data':0,'perf-wrap-full':0,'perf-paint-refresh':0,'perf-respray':0,'perf-livery':0,'perf-decal-kit':0
};
function dynoCalc(){const base=dynoBase[genKey()]||dynoBase.ND;const selected=(state.dyno?.upgrades||[]).map(id=>performanceUpgradeOptions.find(x=>x.id===id)).filter(Boolean);const powerGain=selected.reduce((sum,x)=>sum+(dynoPower[x.id]||0),0);const crank=base.hp+powerGain;const loss=Math.max(5,Math.min(35,Number(state.dyno?.loss)||15));const wheel=crank*(1-loss/100);const addedWeight=selected.reduce((sum,x)=>sum+(x.id==='perf-rollbar'?45:x.id==='perf-wrap-full'?8:x.id==='perf-respray'?30:x.id==='perf-data'?5:0),0);const weight=Math.max(1500,Number(state.dyno?.weight)||base.weight)+addedWeight;const surface=state.dyno?.surface||'street';const grip={street:1,drag:1.08,prep:1.16,wet:.84}[surface]||1;const driver={average:1.0,good:1.06,launch:1.11}[state.dyno?.driver||'average']||1;const powerRatio=Math.sqrt(base.hp/Math.max(1,crank));const weightRatio=Math.sqrt(weight/base.weight);const aero=surface==='drag'?0.96:surface==='prep'?0.94:surface==='wet'?1.1:1;const zero=Math.max(3.2,base.zero*powerRatio*weightRatio*aero/(grip*driver));const low=zero*.94,high=zero*1.08;const q=selected.filter(x=>dynoPower[x.id]>0).map(x=>`${x.name} +${dynoPower[x.id]} hp`);return {base,selected,powerGain,crank,wheel,loss,weight,zero,low,high,traction:grip,q};}
function renderDynoEstimator(){const d=dynoCalc();const gen=genKey();const options=performanceUpgradeOptions.filter(x=>x.generations.includes(gen));return `<section class="dyno-estimator"><div class="dyno-head"><div><span class="eyebrow">Instrument bay / estimate mode</span><h2>Dyno &amp; Drag Racer</h2><p>Model the combination before buying it. Select upgrades, change the car’s weight and drivetrain loss, then switch from a street launch to a prepared drag surface.</p></div><div class="dyno-readout"><span class="eyebrow">${gen} estimate</span><strong>${d.zero.toFixed(2)} sec</strong><small>0–60 expected · ${d.low.toFixed(2)}–${d.high.toFixed(2)} sec band</small></div></div><div class="dyno-controls"><div class="dyno-control-card"><label for="dyno-weight">Curb weight override (lb)</label><input id="dyno-weight" type="number" min="1500" max="4000" step="10" value="${state.dyno?.weight||d.base.weight}" data-field="dyno-weight"><small>Base ${d.base.weight.toLocaleString()} lb · use a measured race weight when possible.</small></div><div class="dyno-control-card"><label for="dyno-loss">Drivetrain loss (%)</label><input id="dyno-loss" type="number" min="5" max="35" step="1" value="${state.dyno?.loss||15}" data-field="dyno-loss"><small>Use a range when comparing dyno types. This is not a dyno correction factor.</small></div><div class="dyno-control-card"><label for="dyno-surface">Launch surface</label><select id="dyno-surface" data-field="dyno-surface"><option value="street" ${state.dyno?.surface==='street'?'selected':''}>Street / normal grip</option><option value="drag" ${state.dyno?.surface==='drag'?'selected':''}>Drag strip</option><option value="prep" ${state.dyno?.surface==='prep'?'selected':''}>Prepared launch pad</option><option value="wet" ${state.dyno?.surface==='wet'?'selected':''}>Wet / low grip</option></select></div><div class="dyno-control-card"><label for="dyno-driver">Driver launch quality</label><select id="dyno-driver" data-field="dyno-driver"><option value="average" ${state.dyno?.driver==='average'?'selected':''}>Average street launch</option><option value="good" ${state.dyno?.driver==='good'?'selected':''}>Good repeatable launch</option><option value="launch" ${state.dyno?.driver==='launch'?'selected':''}>Drag-racer launch</option></select></div></div><div class="dyno-results"><div><span>Estimated crank power</span><strong>${Math.round(d.crank)} hp</strong><small>Base ${d.base.hp} + ${d.powerGain} modeled upgrade hp</small></div><div><span>Estimated wheel power</span><strong>${Math.round(d.wheel)} whp</strong><small>${d.loss}% modeled drivetrain loss</small></div><div><span>Modeled mass</span><strong>${Math.round(d.weight).toLocaleString()} lb</strong><small>Includes modeled upgrade mass</small></div><div><span>Grip multiplier</span><strong>${d.traction.toFixed(2)}×</strong><small>${esc(state.dyno?.surface||'street')} surface assumption</small></div></div><div class="dyno-layout"><div><div class="section-band"><h3>Select upgrades to model</h3><span class="eyebrow">${d.selected.length} selected</span></div><div class="dyno-upgrade-grid">${options.map(o=>`<label class="dyno-upgrade ${state.dyno?.upgrades?.includes(o.id)?'selected':''}"><input type="checkbox" data-action="toggle-dyno-upgrade" data-upgrade="${o.id}" ${state.dyno?.upgrades?.includes(o.id)?'checked':''}><span><strong>${esc(o.name)}</strong><small>${esc(o.category)} · ${dynoPower[o.id]||0} modeled hp · ${esc(o.price)}</small></span></label>`).join('')}</div></div><aside class="dyno-explain"><span class="eyebrow">What is driving the result</span><h3>${d.q.length?d.q.join(' · '):'Select a power-producing upgrade'}</h3><p>Grip upgrades mostly change the launch result. Suspension, brakes, cooling, and safety upgrades improve repeatability and margin but are not free horsepower.</p><div class="notice"><strong>Model limits:</strong> This is a planning estimator, not a dyno graph, ECU calibration, or race timing slip. Tire temperature, launch technique, gearing, altitude, wind, surface prep, and shift time can move the result significantly.</div></aside></div></section>`}
function genKey(value=state.profile.generation){return String(value).slice(0,2).toUpperCase()}
function currentGeneration(){return generations.find(g=>g.id===genKey())||generations[3]}
function showToast(message){const node=$('#toast');if(!node)return;node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),2200)}
function toast(message){showToast(message)}
function record(type,description,cost=0,notes=''){state.history.unshift({id:Date.now()+Math.random(),date:new Date().toISOString().slice(0,10),type,description,cost:Number(cost)||0,notes,mileage:state.profile.mileage})}
function setView(view){state.view=view;render()}
function activeBook(){return books.find(b=>b.id===state.activeBook)||books[0]}
function filteredProcedures(){
  const q=state.query.trim().toLowerCase(); const g=state.generationFilter==='all'?null:state.generationFilter;
  return procedures.filter(p=>p.book===state.activeBook && (!g||p.applies.includes(g)) && (!q||[p.title,p.system,p.symptoms,p.tags.join(' '),p.applies.join(' ')].join(' ').toLowerCase().includes(q)));
}
function render(){
  document.querySelector('#app').innerHTML=`<div class="app-shell">
    ${renderTopbar()}
    ${renderRail()}
    <main class="main" id="main">${renderView()}</main>
    <div class="toast" id="toast" role="status" aria-live="polite"></div>
  </div>`;
  bind();
}
function renderTopbar(){return `<header class="topbar"><div class="brand-lockup"><div class="brand-mark" aria-hidden="true">MM</div><div><div class="brand-name">Modified Miata Bible</div><div class="brand-sub">Factory pit wall edition · service / setup / records</div></div></div><div class="sync-pill"><span class="sync-dot offline"></span> local garage · sync optional</div></header>`}
function renderRail(){return `<aside class="rail" aria-label="Primary navigation"><div class="rail-label">Workbench</div><nav>${navButton('garage','Garage','01')}${navButton('manual','Manual reader','02')}${navButton('genmanual','Generation repair','03')}${navButton('builds','Builds & parts','04')}${navButton('history','History','05')}${navButton('facts','Generations','06')}</nav><div class="rail-label">Manual index</div><nav>${books.slice(0,8).map(b=>`<button class="chapter-link" data-action="open-book" data-book="${b.id}"><span class="chapter-number">${b.number}</span><span>${esc(b.title)}</span></button>`).join('')}</nav><div class="rail-vehicle"><span class="eyebrow">Current vehicle</span><strong>${esc(state.profile.buildName)}</strong><p>${esc(state.profile.year)} · ${esc(genKey())} · ${esc(state.profile.trim)}</p><button class="button text small" data-action="edit-vehicle">Edit profile →</button></div></aside>`}
function navButton(id,label,number){return `<button class="${state.view===id?'active':''}" data-action="view" data-view="${id}"><span class="chapter-number">${number}</span> ${label}</button>`}
function renderView(){
  if(state.view==='manual')return renderManual();
  if(state.view==='builds')return renderBuilds();
  if(state.view==='history')return renderHistory();
  if(state.view==='facts')return renderFacts();
  if(state.view==='genmanual')return renderGenerationManual();
  return renderGarage();
}
function renderHead(kicker,title,deck,actions=''){return `<div class="view-head"><div><div class="view-kicker">${kicker}</div><h1 class="view-title">${title}</h1>${deck?`<p class="view-deck">${deck}</p>`:''}</div><div class="view-actions">${actions}</div></div>`}
function renderGarage(){const g=currentGeneration();const checks=g.watch?.length?g.watch:['Confirm vehicle fitment and service history','Check fluids, leaks, tires, brakes, and battery','Record symptoms before ordering parts'];const installedCost=state.parts.reduce((sum,p)=>sum+p.cost,0);return `<div class="view">${renderHead('01 · vehicle file',`Garage / ${esc(state.profile.buildName)}`,'The place to keep the car as it actually exists: fitment, parts, service history, and the next sensible move.','<button class="button primary" data-action="view" data-view="manual">Open workshop manual</button>')}
  <div class="hero-grid"><div class="hero-photo"><img src="${g.image}" alt="${g.id} generation Mazda MX-5 Miata"><div class="hero-copy"><div class="eyebrow">${g.id} · ${g.years}</div><h2>${g.engine}</h2><p>${esc(g.note)}</p></div></div><div class="hero-stat"><div><span class="stat-label">Current setup</span><div class="fitment-stamp">${g.id} · ${esc(state.profile.market)}</div></div><div><strong>${state.parts.length}</strong><span class="stat-label"> installed changes</span></div><p>${money(installedCost)} tracked parts spend · ${state.history.length} history events</p></div></div>
  <div class="workbench"><section class="sheet" aria-labelledby="garage-profile-title"><div class="index-tabs"><span class="index-tab active">vehicle record</span><span class="index-tab">fitment first</span></div><h2 id="garage-profile-title">The car on the lift</h2><p class="muted">Save the configuration you actually own. The manual and parts screens use it to keep fitment visible.</p>${renderProfileForm()}<div class="section-band"><h2>Next sensible checks</h2><button class="button text" data-action="open-book" data-book="maintenance">Open maintenance →</button></div><div class="quick-grid">${checks.map((item,i)=>`<div class="quick-card"><span class="eyebrow">0${i+1} · watch first</span><h3>${esc(item)}</h3><p>Capture evidence before ordering parts or changing the setup. Open the related manual chapter before buying parts.</p></div>`).join('')}</div></section>${renderContextRail(g)}</div>
  <div class="section-band"><h2>Manual architecture</h2><button class="button text" data-action="view" data-view="manual">Browse all books →</button></div><div class="chapter-list">${books.slice(0,5).map(chapterRow).join('')}</div></div>`}
function renderProfileForm(){return `<div class="form-grid"><div class="field"><label for="profile-name">Build name</label><input id="profile-name" data-field="buildName" value="${esc(state.profile.buildName)}"></div><div class="field"><label for="profile-market">Market</label><select id="profile-market" data-field="market"><option ${state.profile.market==='North America'?'selected':''}>North America</option><option ${state.profile.market==='Japan'?'selected':''}>Japan</option><option ${state.profile.market==='Europe'?'selected':''}>Europe</option><option ${state.profile.market==='Other'?'selected':''}>Other</option></select></div><div class="field"><label for="profile-generation">Generation</label><select id="profile-generation" data-field="generation">${generations.map(g=>`<option value="${g.id}" ${state.profile.generation===g.id?'selected':''}>${g.id} · ${g.years}</option>`).join('')}</select></div><div class="field"><label for="profile-year">Model year</label><input id="profile-year" data-field="year" type="number" min="1989" max="2030" value="${esc(state.profile.year)}"></div><div class="field"><label for="profile-trim">Trim / body</label><input id="profile-trim" data-field="trim" value="${esc(state.profile.trim)}"></div><div class="field"><label for="profile-mileage">Odometer / miles</label><input id="profile-mileage" data-field="mileage" type="number" min="0" value="${esc(state.profile.mileage)}"></div></div><div style="margin-top:16px"><button class="button primary" data-action="save-profile">Save vehicle record</button></div>`}
function renderContextRail(g){return `<aside class="context-rail"><div class="context-card"><h3>Fitment stamp</h3><div class="fitment-stamp">${g.id} · ${esc(state.profile.year)} · ${esc(state.profile.trim)}</div><p>Every repair and part should inherit this context before you spend money.</p></div><div class="context-card"><h3>Build ledger</h3><div class="metric-row"><span>Parts spend</span><b>${money(state.parts.reduce((s,p)=>s+p.cost,0))}</b></div><div class="metric-row"><span>Plan estimate</span><b>${money(state.plan.reduce((s,p)=>s+p.cost,0))}</b></div><div class="metric-row"><span>History events</span><b>${state.history.length}</b></div><button class="button small" data-action="view" data-view="builds">Open build ledger</button></div><div class="context-card"><h3>Save state</h3><p><span class="sync-dot offline"></span> Local copy is active.</p><p>Free Garage stores data on this device. Optional Sync can add encrypted cross-device backup later. Export a backup before changing devices.</p><button class="button small" data-action="export">Export garage JSON</button></div></aside>`}
function chapterRow(book){return `<button class="chapter-row" data-action="open-book" data-book="${book.id}"><span class="num">${book.number}</span><span><strong>${esc(book.title)}</strong><small>${esc(book.description)}</small></span><span class="pages">${book.pages} pp</span></button>`}
function renderDiagnosticFinder(){const q=state.query.trim().toLowerCase();const trees=diagnosticTrees.filter(t=>!q||[t.title,t.entry,t.symptoms.join(' '),t.firstChecks.join(' '),t.branches.map(b=>`${b.when} ${b.meaning}`).join(' '),t.applies.join(' '),t.related.join(' ')].join(' ').toLowerCase().includes(q));return `<section class="diagnostic-finder" aria-labelledby="diagnostic-finder-title"><div class="section-band"><h2 id="diagnostic-finder-title">Symptom router</h2><span class="eyebrow">${trees.length} matching diagnostic trees</span></div><p class="muted">Search the complaint in plain language. Start with evidence, follow the branch that matches the test result, and open the linked canonical procedures only after the fault domain is narrowed.</p><div class="diagnostic-tree-list">${trees.length?trees.map(renderDiagnosticTree).join(''):`<div class="empty-state"><h3>No symptom tree matches that search.</h3><p>Try “no start”, “overheat”, “battery”, “brake pull”, “water”, “ABS”, or “vibration”.</p></div>`}</div></section>`}
function renderDiagnosticTree(t){return `<details class="diagnostic-tree" open><summary><div class="procedure-title">${esc(t.title)}</div><div class="procedure-meta">${t.applies.map(g=>`<span class="meta-tag">${g}</span>`).join('')}<span class="meta-tag">symptom router</span></div></summary><div class="diagnostic-tree-body"><p><strong>Entry condition:</strong> ${esc(t.entry)}</p><div class="diagnostic-columns"><div><h4>Start here</h4><ol>${t.firstChecks.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="notice danger"><strong>Stop driving / escalate</strong><p>${esc(t.stop)}</p></div></div><h4>Branch on the evidence</h4><div class="diagnostic-branches">${t.branches.map(b=>`<article class="diagnostic-branch"><strong>IF</strong><p>${esc(b.when)}</p><strong>THEN</strong><p>${esc(b.meaning)}</p><span class="fitment-stamp">next: ${esc(b.next)}</span></article>`).join('')}</div><div class="diagnostic-evidence"><div><strong>Fact</strong><p>${esc(t.facts)}</p></div><div><strong>Common myth</strong><p>${esc(t.misconception)}</p></div><div><strong>Verify</strong><p>${esc(t.unknown)}</p></div></div><p class="muted"><strong>Canonical procedures:</strong> ${t.related.map(id=>{const p=procedures.find(x=>x.id===id);return p?esc(p.title):esc(id)}).join(' · ')}</p></div></details>`}
function renderManual(){const book=activeBook();const list=filteredProcedures();return `<div class="view">${renderHead('02 · workshop manual',book.title,'A structured, original reference layer. Filter by chassis before reading a procedure; verify exact specifications against authorized service information.','<button class="button" data-action="print">Print chapter</button>')}
  <div class="top-nav" aria-label="Primary navigation">${navButton('garage','Garage','01')}${navButton('manual','Manual','02')}${navButton('genmanual','Generation repair','03')}${navButton('builds','Builds','04')}${navButton('history','History','05')}${navButton('facts','Facts','06')}</div>
  <div class="workbench"><section class="sheet"><div class="index-tabs"><span class="index-tab active">book ${book.number}</span><span class="index-tab">original content</span><span class="index-tab">fitment-aware</span></div><div class="notice danger"><strong>Use this as a companion reference.</strong> Exact torque values, wiring, fluid specifications, and safety procedures vary by year, market, engine, trim, and modification. Verify them in the correct service information before work.</div><div class="filter-bar"><input class="search-input" aria-label="Search this manual" placeholder="Search title, symptom, system, tag…" value="${esc(state.query)}" data-field="query"><select class="search-input" aria-label="Filter by generation" data-field="generationFilter"><option value="all">All generations</option>${generations.map(g=>`<option value="${g.id}" ${state.generationFilter===g.id?'selected':''}>${g.id} · ${g.years}</option>`).join('')}</select><button class="button" data-action="clear-search">Clear filters</button></div>${book.id==='diagnostics'?renderDiagnosticFinder():''}<div class="procedure-list">${list.length?list.map(renderProcedure).join(''):`<div class="empty-state"><h3>No procedure matches this filter.</h3><p>Try another generation, system, or symptom. Do not broaden fitment assumptions just to make a part fit.</p></div>`}</div></section><aside class="context-rail"><div class="context-card"><h3>Manual index</h3><div class="chapter-list">${books.map(b=>`<button class="chapter-link ${b.id===book.id?'active':''}" data-action="open-book" data-book="${b.id}"><span class="chapter-number">${b.number}</span><span>${esc(b.title)}</span></button>`).join('')}</div></div><div class="context-card"><h3>Reading state</h3><div class="metric-row"><span>Procedures in book</span><b>${procedures.filter(p=>p.book===book.id).length}</b></div><div class="metric-row"><span>Diagnostic trees</span><b>${book.id==='diagnostics'?diagnosticTrees.length:'—'}</b></div><div class="metric-row"><span>Saved procedures</span><b>${state.savedProcedures.length}</b></div><p>Use the save control inside a procedure to build your own service queue.</p></div></aside></div></div>`}
function renderProcedure(p){
  const saved=state.savedProcedures.includes(p.id);
  const recs=p.recommendations?.length?`<section class="recommendation-panel" aria-labelledby="recommended-parts-${esc(p.id)}"><div class="section-band"><h4 id="recommended-parts-${esc(p.id)}">Recommended parts & buying logic</h4><span class="eyebrow">editorial / fitment-aware</span></div><div class="recommendation-list">${p.recommendations.map(r=>`<article class="recommendation-card"><div><span class="eyebrow">${esc(r.kind)}</span><h5>${esc(r.name)}</h5><p>${esc(r.why)}</p></div><a class="button text small" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">View product ↗</a></article>`).join('')}</div><p class="recommendation-disclosure">${esc(p.recommendationDisclosure||'Product links are editorial suggestions. Verify fitment, current pricing, warranty, and installation instructions before purchase.')}</p></section>`:'';
  return `<details class="procedure-card" ${saved?'open':''}><summary><div class="procedure-title">${esc(p.title)}</div><div class="procedure-meta"><span class="meta-tag">${esc(p.system)}</span><span class="meta-tag">${esc(p.difficulty)}</span><span class="meta-tag">${esc(p.time)}</span>${p.applies.map(g=>`<span class="meta-tag">${g}</span>`).join('')}</div></summary><div class="procedure-body"><p><strong>Use when:</strong> ${esc(p.symptoms)}</p><h4>Before you begin</h4><div class="notice danger">${esc(p.safety)}</div><h4>Tools & supplies</h4><ul>${p.tools.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${recs}<h4>Procedure</h4><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h4>Verification</h4><p>${esc(p.verify)}</p><h4>Common mistakes</h4><p>${esc(p.mistakes)}</p><div class="notice"><strong>Sources to check:</strong> ${p.sources.map(s=>esc(s)).join(' · ')}</div><div style="display:flex;gap:12px;flex-wrap:wrap"><button class="button small ${saved?'primary':''}" data-action="save-procedure" data-id="${p.id}">${saved?'Saved to queue':'Save to service queue'}</button><button class="button text small" data-action="view" data-view="builds">Open parts / build ledger →</button></div></div></details>`;
}
const upgradeRules={
  'coilovers':{required:[{name:'Professional four-wheel alignment',cost:180,reason:'Ride height and damper changes alter toe, camber, and steering behavior.',source:'alignment-four-wheel'}],recommended:[{name:'Corner balance and setup session',cost:275,reason:'Makes adjustable suspension settings repeatable with driver/load assumptions recorded.'}],warnings:['Check bump travel, spring preload, tire clearance, brake-line routing, and soft-top/RF clearance before final ride height.']},
  'tires-200tw':{required:[{name:'Professional four-wheel alignment',cost:180,reason:'New grip exposes alignment errors and can make a car unstable if toe is wrong.',source:'alignment-four-wheel'}],recommended:[{name:'Corner balance and setup session',cost:275,reason:'Useful when the car has adjustable suspension or is being prepared for track use.'}],warnings:['Verify wheel width, offset, tire age, cold pressure baseline, fender clearance, and wet-weather use.']},
  'pads-track':{required:[{name:'High-temperature brake fluid service',cost:95,reason:'Track-capable pads need a known fluid baseline and a complete brake inspection.',source:'brake-fluid-high-temp'}],recommended:[{name:'Brake rotor and hose inspection',cost:120,reason:'Pad changes do not fix cracked rotors, seized pistons, damaged hoses, or uneven caliper action.'}],warnings:['Pad compound, rotor temperature, tire grip, and pedal feel must be treated as one system.']},
  'sway-bar':{required:[{name:'Professional four-wheel alignment',cost:180,reason:'Changing roll stiffness can change the balance and exposes worn bushings or end links.',source:'alignment-four-wheel'}],recommended:[{name:'Replacement end-link and bushing inspection',cost:80,reason:'New bars are wasted if the mounting hardware or links are loose, seized, or cracked.'}],warnings:['Adjustable bars can create snap oversteer or understeer if installed without a neutral baseline.']},
  'clutch-flywheel-na-nb':{required:[{name:'Pilot and release bearing service kit',cost:95,reason:'The transmission is already out; old bearings can undo the value of the upgrade.'},{name:'Clutch hydraulic inspection / bleed',cost:75,reason:'A worn master, slave, hose, or air in the circuit can mimic a bad clutch.'}],recommended:[{name:'Rear main seal inspection',cost:35,reason:'Oil contamination is easier to address before the flywheel and clutch hide the crank flange.'}],warnings:['Confirm 1.6/1.8, clutch diameter, flywheel step, torque target, and break-in instructions before ordering.']},
  'clutch-flywheel-nc':{required:[{name:'Pilot and release bearing service kit',cost:120,reason:'Replace wear items while the NC powertrain is open.'},{name:'Clutch hydraulic inspection / bleed',cost:90,reason:'The release system must be proven before blaming the new friction assembly.'}],recommended:[{name:'Rear main seal inspection',cost:45,reason:'Correct oil leaks before installing clean friction surfaces.'}],warnings:['Verify NC revision, clutch diameter, flywheel compatibility, PPF/driveline alignment, and heat-shield restoration.']},
  'clutch-flywheel-nd':{required:[{name:'Pilot and release bearing service kit',cost:150,reason:'The access labor is substantial; renewing wear items protects the job.'},{name:'Post-install scan and clutch-system check',cost:110,reason:'ND low-voltage, network, and warning-lamp issues need to be checked after reconnecting the battery.'}],recommended:[{name:'Rear main seal inspection',cost:55,reason:'Address contamination before installing the new clutch and flywheel.'}],warnings:['Confirm ND1/ND2/ND3, engine, transmission, RF/soft-top fitment, warranty implications, and kit-specific flywheel requirements.']}
};
const topRecommendations=[
  {id:'top-tires-200tw',name:'200-treadwear performance tire set',category:'Grip / safety',price:760,shipping:45,why:'The most immediately felt upgrade for braking, cornering, and confidence. Buy by size, load rating, weather use, and wheel fitment—not just treadwear number.',link:'https://www.tirerack.com/tires/types/200tw-summer-tires',source:'Tire Rack 200TW category'},
  {id:'top-coilovers',name:'Generation-matched adjustable damper package',category:'Suspension',price:1450,shipping:95,why:'Adds control and ride-height adjustability, but only becomes a good buy when paired with alignment, bump-travel checks, and sensible spring rates.',link:'https://949racing.com/supermiata/',source:'949 Racing SuperMiata catalog'},
  {id:'top-cooling',name:'Generation-specific cooling-system refresh',category:'Reliability',price:430,shipping:35,why:'Cooling margin protects the engine before power mods. Budget for hoses, thermostat, cap, clamps, coolant, fan verification, and a proper bleed—not only a radiator.',link:'https://flyinmiata.com/',source:'Flyin’ Miata catalog'}
];
function shippingMultiplier(){const zip=String(state.estimateZip||'').match(/\b\d{5}\b/);if(!zip)return 1;const zone=zip[0][0];return zone==='0'||zone==='1'?0.9:zone==='2'||zone==='3'?0.95:zone==='4'||zone==='5'?1:zone==='6'||zone==='7'?1.08:1.16}
function deliveredEstimate(item){const shipping=Math.round(item.shipping*shippingMultiplier());const subtotal=item.price+shipping;const tax=Math.round(subtotal*(Number(state.taxRate)||0)/100);return {shipping,tax,total:subtotal+tax};}
function renderTopRecommendations(){return `<section class="top-recommendations"><div class="section-band"><h2>Top 3 starting recommendations</h2><span class="eyebrow">editorial · verify fitment</span></div><p class="muted">These are broad starting points for a healthy Miata, not universal orders. Prices are planning estimates; supplier price, stock, destination, sales tax, and oversized-package rules can change. Shipping adjusts by ZIP zone when entered, but only the retailer can quote the final delivered price.</p><div class="top-rec-grid">${topRecommendations.map(item=>{const d=deliveredEstimate(item);return `<article class="top-rec-card"><div class="eyebrow">${esc(item.category)} · ${esc(genKey())} review</div><h3>${esc(item.name)}</h3><p>${esc(item.why)}</p><div class="top-rec-cost"><span>Part est. <b>${money(item.price)}</b></span><span>Ship est. <b>${money(d.shipping)}</b></span><span>Tax est. <b>${money(d.tax)}</b></span><strong>Delivered est. ${money(d.total)}</strong></div><div class="top-rec-actions"><a class="button text small" href="${esc(item.link)}" target="_blank" rel="noopener noreferrer">View ${esc(item.source)} ↗</a><button class="button small" data-action="add-top-recommendation" data-name="${esc(item.name)}" data-cost="${item.price}" data-notes="${esc(item.why)}">Add to estimate</button></div></article>`}).join('')}</div></section>`}
function inferredRule(item){
  if(upgradeRules[item.source])return upgradeRules[item.source];
  const n=(item.name||'').toLowerCase();
  if(/turbo|supercharg|forced induction/.test(n))return {required:[{name:'Fuel system sizing and pressure verification',cost:250,reason:'Forced induction needs verified fuel delivery before boost is applied.'},{name:'Wideband oxygen sensor and safe calibration',cost:350,reason:'A boost project needs measured mixture data and a calibration strategy.'}],recommended:[{name:'Clutch torque-capacity review',cost:0,reason:'The stock clutch may become the limiting part after torque rises.'}],warnings:['Do not run a new boost system on an unknown cooling, fuel, oil, or ignition baseline.']};
  if(/coilover|damper|suspension/.test(n))return upgradeRules.coilovers;
  if(/tire|wheel/.test(n))return upgradeRules['tires-200tw'];
  if(/brake|pad|rotor/.test(n))return upgradeRules['pads-track'];
  if(/clutch|flywheel/.test(n))return upgradeRules['clutch-flywheel-na-nb'];
  if(/roll bar|harness|seat/.test(n))return {required:[{name:'Seat, belt, helmet, and harness compatibility review',cost:0,reason:'Occupant restraints must work together; a roll bar is not automatically safe with every seat or harness.',source:null}],recommended:[{name:'Professional installation inspection',cost:150,reason:'Verify clearance, mounting, head position, and soft-top or RF operation.'}],warnings:['Do not combine a harness, fixed-back seat, roll bar, and factory airbags without understanding the complete occupant-protection system.']};
  return {required:[],recommended:[],warnings:[]};
}
function planSuggestions(){
  const selected=new Set(state.plan.map(x=>x.source||x.name));
  const required=[],recommended=[],warnings=[];
  state.plan.forEach(item=>{const rule=inferredRule(item);(rule.required||[]).forEach(x=>{if(!selected.has(x.source||x.name))required.push({...x,from:item.name})});(rule.recommended||[]).forEach(x=>{if(!selected.has(x.source||x.name))recommended.push({...x,from:item.name})});(rule.warnings||[]).forEach(x=>warnings.push({text:x,from:item.name}))});
  const dedupe=a=>a.filter((x,i)=>a.findIndex(y=>y.name===x.name)===i);
  return {required:dedupe(required),recommended:dedupe(recommended),warnings:dedupe(warnings)};
}
function renderPlanItem(item){return `<div class="part-row"><div><div class="fitment-stamp">${esc(item.category||'Planned part')} · ${esc(item.generation||genKey())}</div><h3>${esc(item.name)}</h3><p>${esc(item.notes||'No notes yet.')} ${item.source?'· catalog item':''}</p></div><div><div class="price">${money(item.cost)}</div><button class="button text small" data-action="remove-plan" data-id="${item.id}">Remove</button></div></div>`}
function renderSuggestion(item,kind){return `<article class="suggestion-card ${kind}"><div><span class="eyebrow">${kind==='required'?'required companion':'strongly recommended'} · from ${esc(item.from)}</span><h3>${esc(item.name)}</h3><p>${esc(item.reason)}</p></div><div class="suggestion-actions"><strong>${item.cost?money(item.cost):'review'}</strong><button class="button small" data-action="add-suggestion" data-name="${esc(item.name)}" data-source="${esc(item.source||'')}" data-cost="${item.cost||0}" data-notes="${esc(item.reason)}">${item.cost?'Add to estimate':'Add note'}</button></div></article>`}
function renderStreetBuildOptions(){return `<div class="street-build-library"><div class="section-band"><h2>Reliable Street Build library</h2><span class="eyebrow">12 paths · compare before you buy</span></div><p class="muted">Start with the goal, not the loudest part. These paths are deliberately different: a comfortable commuter, a hot-climate daily, a back-road car, and a boost-ready chassis should not share one shopping list.</p><div class="street-option-grid">${streetBuildOptions.map(o=>`<article class="street-option-card"><div class="street-option-head"><span class="eyebrow">${esc(o.stage)} · ${esc(o.budget)}</span><span class="fitment-stamp">${esc(o.bestFor)}</span></div><h3>${esc(o.title)}</h3><p>${esc(o.summary)}</p><div class="street-option-parts"><strong>Starts with</strong><span>${o.items.map(id=>{const part=parts.find(p=>p.id===id);return part?esc(part.name):esc(id)}).join(' · ')}</span></div><div class="notice"><strong>Watch:</strong> ${esc(o.watchouts)}</div><button class="button primary small" data-action="load-street-option" data-option="${esc(o.id)}">Load this path →</button></article>`).join('')}</div></div>`}
function renderPerformanceUpgrades(){const g=genKey();const options=performanceUpgradeOptions.filter(x=>x.generations.includes(g));return `<div class="view">${renderHead('04 · performance catalog','Performance upgrades','Compare performance parts by goal, generation, price, product source, and supporting work before anything gets ordered.','<button class="button primary" data-action="build-tab" data-tab="future">Open Future Build</button>')}<section class="performance-hero"><div class="performance-hero-copy"><span class="eyebrow">Modified Miata performance lab</span><h2>Build the feel.<br><em>Keep the car.</em></h2><p>Upgrade by outcome—grip, response, thermal margin, confidence, or identity. Every card shows the supporting work before the checkout link.</p><div class="hero-metrics"><span><b>${options.length}</b> fitment-matched paths</span><span><b>DIY + shop</b> labor view</span><span><b>NA · NB · NC · ND</b> coverage</span></div></div><div class="performance-hero-visual"><div class="dial dial-one"><span>GRIP</span><b>+02</b></div><div class="dial dial-two"><span>HEAT</span><b>+04</b></div><div class="dial dial-three"><span>FEEL</span><b>+07</b></div><div class="hero-grid-line"></div><div class="hero-caption">SETUP / EVIDENCE / REPEAT</div></div></section><div class="build-tabs"><button class="button" data-action="build-tab" data-tab="future">Future build</button><button class="button primary" data-action="build-tab" data-tab="performance">Performance upgrades</button><button class="button" data-action="build-tab" data-tab="installed">Installed parts</button></div><div class="performance-toolbar"><div><span class="eyebrow">Fitment stamp</span><strong>${g} · ${esc(state.profile.year)} · ${esc(state.profile.trim)}</strong></div><div><span class="eyebrow">Catalog depth</span><strong>${options.length} matched options</strong></div><p>Prices are planning ranges, not live quotes. Product links open the retailer or manufacturer page; verify current fitment, stock, shipping, tax, warranty, and legal requirements.</p></div>${renderDynoEstimator()}<div class="performance-grid">${options.map(o=>`<details class="performance-card"><summary><div class="performance-card-top"><span class="eyebrow">${esc(o.category)}</span><span class="price-range">${esc(o.price)}</span></div><h3>${esc(o.name)}</h3><span class="performance-open">View rationale, dependencies, and product link +</span></summary><div class="performance-body"><p>${esc(o.why)}</p><div class="performance-labor"><strong>Labor estimate</strong><p>${esc(o.labor||laborFor(o.id))}</p><small>Shop range assumes a competent independent Miata shop; rust, seized hardware, paint repair, setup changes, and diagnosis can add time.</small></div><div class="performance-dependency"><strong>Supporting work / required checks</strong><p>${esc(o.requires)}</p></div><div class="performance-actions"><a class="button primary small" href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">${esc(o.retailer)} ↗</a><button class="button small" data-action="add-performance" data-performance="${esc(o.id)}">Add to Future Build</button></div></div></details>`).join('')}</div><section class="other-upgrade-panel"><div><span class="eyebrow">Not in the catalog?</span><h2>Add an Other upgrade</h2><p>Enter your own part, service, shop quote, or sponsor product. It will be added to Future Build with a fitment note.</p></div><div class="other-upgrade-form"><input id="other-upgrade-name" placeholder="Part or service name"><input id="other-upgrade-cost" type="number" min="0" placeholder="Estimated price"><input id="other-upgrade-url" type="url" placeholder="Product link (optional)"><button class="button primary" data-action="add-other-upgrade">Add Other to Future Build</button></div></section></div>`}
function renderBuilds(){
  if(state.buildTab==='performance')return renderPerformanceUpgrades();
  const total=state.plan.reduce((s,p)=>s+Number(p.cost||0),0);
  const suggestions=planSuggestions();
  const estimate=state.buildTab!=='installed';
  return `<div class="view">${renderHead('03 · build ledger',estimate?'Future build / parts planner':'Build ledger / installed parts','Enter what you want to buy. The planner adds the running estimate and calls out required companions, strongly recommended support work, and fitment warnings.','<button class="button primary" data-action="export">Export garage JSON</button>')}
  <div class="build-tabs"><button class="button ${estimate?'primary':''}" data-action="build-tab" data-tab="future">Future build</button><button class="button ${state.buildTab==='performance'?'primary':''}" data-action="build-tab" data-tab="performance">Performance upgrades</button><button class="button ${!estimate?'primary':''}" data-action="build-tab" data-tab="installed">Installed parts</button></div>
  <div class="workbench"><section class="sheet">${estimate?`<div class="index-tabs"><span class="index-tab active">future build</span><span class="index-tab">dependencies</span><span class="index-tab">fitment first</span></div><h2>${esc(state.planName)}</h2><p class="muted">Add catalog parts or enter a custom part. This is an estimate, not permission to skip fitment, safety, or the correct service information.</p>${renderTopRecommendations()}<div class="custom-part-form"><div class="field"><label for="custom-part-name">Part or service you want to buy</label><input id="custom-part-name" placeholder="Example: turbo kit, clutch, coilovers, roll bar"></div><div class="field"><label for="custom-part-cost">Estimated cost (USD)</label><input id="custom-part-cost" type="number" min="0" value="0"></div><button class="button primary" data-action="add-custom-plan">Add to estimated build</button></div><div class="section-band"><h2>Catalog parts</h2><span class="eyebrow">click to add</span></div><div class="procedure-list">${parts.filter(p=>p.generations.includes(genKey())).map(p=>`<div class="procedure-card"><div class="procedure-title">${esc(p.name)}</div><div class="procedure-meta"><span class="meta-tag">${esc(p.category)}</span><span class="meta-tag">${money(p.cost)}</span><span class="meta-tag">${genKey()} fitment</span></div><p>${esc(p.impact)}</p><p class="muted"><strong>Fitment check:</strong> ${esc(p.prereq)}</p><div class="catalog-buy-row"><strong>Planning price ${money(p.cost)}</strong><span>${esc(laborFor(p.id))}</span>${catalogLink(p.id)}</div><button class="button small" data-action="add-plan" data-part="${p.id}">Add to estimate</button></div>`).join('')}</div><div class="section-band"><h2>Current estimate</h2><span class="eyebrow">${state.plan.length} line items</span></div>${state.plan.length?state.plan.map(renderPlanItem).join(''):`<div class="empty-state"><h3>Your estimate is empty.</h3><p>Add a part above. Recommendations will appear when the selected upgrade creates dependencies.</p></div>`}</section><aside class="context-rail"><div class="context-card"><h3>Budget</h3><div class="metric-row"><span>Budget ceiling</span><b>${money(state.budget)}</b></div><div class="metric-row"><span>Planned total</span><b>${money(total)}</b></div><div class="metric-row"><span>Remaining</span><b class="${total>state.budget?'warn':''}">${money(state.budget-total)}</b></div><div class="field"><label for="budget-input">Budget (USD)</label><input id="budget-input" type="number" value="${state.budget}" data-field="budget"></div><div class="field"><label for="plan-name">Plan name</label><input id="plan-name" value="${esc(state.planName)}" data-field="planName"></div><div class="field"><label for="estimate-address">Shipping address (local estimate only)</label><textarea id="estimate-address" rows="2" placeholder="Street, city, state, ZIP" data-field="estimateAddress">${esc(state.estimateAddress||'')}</textarea></div><div class="field"><label for="estimate-zip">Destination ZIP (optional)</label><input id="estimate-zip" value="${esc(state.estimateZip||'')}" placeholder="e.g. 90210" data-field="estimateZip"></div><div class="field"><label for="tax-rate">Estimated sales tax %</label><input id="tax-rate" type="number" min="0" max="20" step="0.1" value="${state.taxRate}" data-field="taxRate"></div><button class="button small primary" data-action="save-plan">Save plan settings</button></div><div class="context-card"><h3>Required companions</h3>${suggestions.required.length?suggestions.required.map(x=>renderSuggestion(x,'required')).join(''):'<p>No mandatory companion items detected yet. Add the upgrade you are considering.</p>'}</div><div class="context-card"><h3>Strongly recommended</h3>${suggestions.recommended.length?suggestions.recommended.map(x=>renderSuggestion(x,'recommended')).join(''):'<p>No additional recommendations yet.</p>'}</div>${suggestions.warnings.length?`<div class="context-card"><h3>Stop and check</h3>${suggestions.warnings.map(x=>`<div class="notice danger"><strong>${esc(x.from)}</strong><br>${esc(x.text)}</div>`).join('')}</div>`:''}<div class="context-card"><h3>Suggested paths</h3>${buildPaths.map(path=>`<div class="build-card" style="margin:8px 0;padding:12px"><h3 style="font-size:19px">${esc(path.title)}</h3><p>${esc(path.summary)}</p><button class="button text small" data-action="load-path" data-path="${path.id}">Load path →</button></div>`).join('')}</div>${renderStreetBuildOptions()}</aside></div></div>`:`<div class="workbench"><section class="sheet"><div class="section-band"><h2>Current installed parts</h2><span class="eyebrow">what is actually on the car</span></div>${state.parts.length?state.parts.map(renderPart).join(''):`<div class="empty-state"><h3>Nothing installed yet.</h3><p>Install or record a part only after it is actually on the car.</p></div>`}</section><aside class="context-rail"><div class="context-card"><h3>Next step</h3><p>Switch to Future build to plan purchases and see required companion work before you install anything.</p><button class="button primary small" data-action="build-tab" data-tab="estimate">Open Future build</button></div></aside></div>`}</div>`;
}
function renderPart(p){return `<div class="part-row"><div><div class="fitment-stamp">${esc(p.category)} · ${esc(p.slot)}</div><h3>${esc(p.part)}</h3><p>${esc(p.notes||'No install notes yet.')} · installed ${esc(p.date)}</p></div><div><div class="price">${money(p.cost)}</div><button class="button text small" data-action="remove-part" data-id="${p.id}">Archive</button></div></div>`}
function renderHistory(){return `<div class="view">${renderHead('04 · service ledger','History / every mile','A plain-language record of what changed, why it changed, and what it cost.','<button class="button primary" data-action="export">Export history</button>')}<div class="workbench"><section class="sheet"><div class="index-tabs"><span class="index-tab active">append-only ledger</span><span class="index-tab">service notes</span></div><h2>Record service</h2><div class="form-grid"><div class="field"><label for="history-type">Type</label><select id="history-type"><option>Service</option><option>Repair</option><option>Inspection</option><option>Modification</option><option>Note</option></select></div><div class="field"><label for="history-cost">Cost (USD)</label><input id="history-cost" type="number" min="0" value="0"></div></div><div class="field"><label for="history-title">What happened?</label><input id="history-title" placeholder="Timing belt and water pump service"></div><div class="field"><label for="history-notes">Notes</label><textarea id="history-notes" placeholder="Parts, measurements, symptoms, next check…"></textarea></div><button class="button primary" data-action="add-history">Add ledger entry</button><div class="section-band"><h2>Recorded work</h2><span class="eyebrow">${state.history.length} events</span></div>${state.history.length?state.history.map(h=>`<div class="history-row"><div><div class="fitment-stamp">${esc(h.type)} · ${esc(h.date)}</div><h3>${esc(h.description)}</h3><p>${esc(h.notes||'No notes recorded.')} · ${Number(h.mileage||0).toLocaleString()} mi</p></div><div class="price">${money(h.cost)}</div></div>`).join(''):`<div class="empty-state">Your service ledger is empty. Add the first honest note.</div>`}</section><aside class="context-rail"><div class="context-card"><h3>Ledger rules</h3><p>Entries are append-only in this version. Replaced parts stay visible so future-you can understand the car’s history.</p><div class="metric-row"><span>Vehicle mileage</span><b>${Number(state.profile.mileage).toLocaleString()}</b></div><div class="metric-row"><span>Tracked spend</span><b>${money(state.history.reduce((s,h)=>s+h.cost,0))}</b></div></div></aside></div></div>`}
function renderGenerationManual(){
  const id=state.generationManual||genKey();
  const manual=generationManuals.find(x=>x.id===id)||generationManuals[0];
  const gen=generations.find(x=>x.id===id)||generations[0];
  return `<div class="view">${renderHead('03 · generation field manual',`${id} / repair procedures`,'A generation-specific reference layer assembled from the research notes. It keeps chassis caveats, safe sequencing, and source links next to the procedures instead of flattening every Miata into one generic car.','<button class="button" data-action="print">Print generation file</button>')}
    <div class="index-tabs">${generationManuals.map(m=>`<button class="index-tab ${m.id===id?'active':''}" data-action="generation-manual" data-generation="${m.id}">${m.id} file</button>`).join('')}</div>
    <div class="notice danger"><strong>Original diagnostic reference, not a factory schematic.</strong> The circuit maps below are functional abstractions. They intentionally omit proprietary pinouts, connector cavities, wire colors, fuse art, and copied factory-manual language. Confirm exact VIN, market, model year, engine, trim, equipment, and modifications before testing.</div>
    <div class="workbench"><section class="sheet"><div class="hero-grid" style="grid-template-columns:.7fr 1.3fr"><div class="hero-stat" style="min-height:215px"><span class="stat-label">Selected chassis</span><strong>${id}</strong><p>${esc(gen.years)} · ${esc(gen.engine)}</p></div><div class="context-card" style="background:var(--ink-2);border:0"><h3>Fitment brief</h3><p>${esc(gen.note)}</p><div class="metric-row"><span>Research files</span><b>${manual.docs.length}</b></div><div class="metric-row"><span>Coverage</span><b>Procedures + systems</b></div></div></div>
      <div class="section-band"><h2>Original circuit maps</h2><span class="eyebrow">functional logic · no pinouts</span></div>${renderCircuitMaps(id)}
      <div class="section-band"><h2>Field procedures</h2><span class="eyebrow">${manual.docs.length} research files</span></div>${manual.docs.map(doc=>`<details class="procedure-card" open><summary><div class="procedure-title">${esc(doc.title)}</div><div class="procedure-meta"><span class="meta-tag">${id}</span><span class="meta-tag">source-backed</span><span class="meta-tag">original synthesis</span></div></summary><div class="procedure-body generation-copy">${renderMarkdown(doc.markdown)}</div></details>`).join('')}</section><aside class="context-rail"><div class="context-card"><h3>${id} watch list</h3>${gen.watch.map((w,i)=>`<div class="metric-row"><span>0${i+1}</span><b style="font-family:var(--body);font-size:12px;text-align:right">${esc(w)}</b></div>`).join('')}</div><div class="context-card"><h3>Source trail</h3><p>Each research file retains public references and model-year caveats. Open the repository note when you need the complete citation list.</p>${manual.docs.map(doc=>`<a class="button text small" href="${doc.file}" target="_blank" rel="noreferrer">${esc(doc.file.split('/').pop())} ↗</a>`).join('')}</div><div class="context-card"><h3>Safety boundary</h3><p>ABS, SRS/airbag, immobilizer, PRHT/RF roof, networked low-voltage faults, and structural corrosion are escalation points. The app can help organize diagnosis; it cannot make an unsafe repair safe.</p></div></aside></div></div>`;
}
function renderMarkdown(markdown){
  const lines=markdown.split(/\r?\n/); let out=''; let inFence=false; let fence=[]; let listType='';
  const closeList=()=>{if(listType){out+=`</${listType}>`;listType='';}};
  for(const line of lines){
    if(line.startsWith('```')){if(!inFence){closeList();inFence=true;fence=[];}else{inFence=false;out+=`<div class="diagram-source"><div class="eyebrow">editable source abstraction</div><pre>${esc(fence.join('\n'))}</pre></div>`;}continue;}
    if(inFence){fence.push(line);continue;}
    if(!line.trim()){closeList();continue;}
    let m=line.match(/^(#{1,4})\s+(.*)$/); if(m){closeList();const level=Math.min(4,m[1].length);out+=`<h${level}>${inlineMarkdown(m[2])}</h${level}>`;continue;}
    m=line.match(/^\s*[-*]\s+(.*)$/); if(m){if(listType!=='ul'){closeList();out+='<ul>';listType='ul';}out+=`<li>${inlineMarkdown(m[1])}</li>`;continue;}
    m=line.match(/^\s*\d+\.\s+(.*)$/); if(m){if(listType!=='ol'){closeList();out+='<ol>';listType='ol';}out+=`<li>${inlineMarkdown(m[1])}</li>`;continue;}
    closeList();
    if(line.startsWith('> ')){out+=`<div class="notice">${inlineMarkdown(line.slice(2))}</div>`;continue;}
    out+=`<p>${inlineMarkdown(line)}</p>`;
  }
  closeList(); if(inFence)out+=`<div class="diagram-source"><pre>${esc(fence.join('\n'))}</pre></div>`; return out;
}
function inlineMarkdown(text){return esc(text).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\(([^)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1 ↗</a>');}
const circuitMaps={
  NA:[['Starting path',['Battery +','Protection / distribution','Ignition + interlock','Starter control','Starter motor','Engine / body ground','Battery −']],['Charging path',['Alternator output','High-current protection','Battery + / loads','Engine case ground','Battery −']],['Fuel enable path',['Key / ECU logic','Circuit-opening relay','Pump + harness','Fuel pump','Rail / regulator','Ground return']]],
  NB:[['Start and engine-control boundary',['Battery / fuse','Ignition + interlock','Starter control','Crank / cam inputs','PCM command','Starter / coils / injectors']],['Fuel-pump chain',['Battery +','Fuse / relay feed','PCM relay control','Pump harness','Pump','Rail / return']],['Lighting branches',['Protected supply','Switch / relay','Function fuse','Lamp branch','Socket / ground']]],
  NC:[['Networked low-voltage path',['Battery + / sensor','Main fuse / distribution','Ground network','PCM / ABS / DSC / body modules','Starter / loads','Battery −']],['Cooling-fan logic',['Temp / A/C request','Control module','Fan fuse / relay','Fan motor','Ground']],['SRS boundary',['SRS module','Yellow harness / initiator','Warning cluster','Trained scan / repair']]],
  ND:[['Low-voltage cascade',['Battery + / current sensor','Main distribution','Engine / body grounds','Networked modules','Windows / keyless / RF / DSC','Battery −']],['RF roof interlock',['Roof request','Ignition / neutral / brake / trunk / speed','Roof controller','Motors / latches / position','Window coordination']],['ND cooling logic',['Temperature data','PCM / control request','Fuse / relay','Fan motor','Airflow / coolant verification']]]
};
function renderCircuitMaps(id){return `<div class="circuit-stack">${(circuitMaps[id]||[]).map(([title,nodes])=>`<article class="circuit-card"><div class="eyebrow">${esc(id)} · original functional map</div><h3>${esc(title)}</h3><p class="muted">Trace the circuit as a sequence of requirements. A failed upstream condition can make a good downstream part look bad.</p><div class="circuit-flow" role="img" aria-label="${esc(title)} functional circuit map">${nodes.map((n,i)=>`<span class="circuit-node">${esc(n)}</span>${i<nodes.length-1?'<span class="circuit-arrow" aria-hidden="true">→</span>':''}`).join('')}</div><p class="diagram-caption">Not a factory schematic. No connector cavities, wire colors, fuse numbers, or pinouts are implied.</p></article>`).join('')}</div>`}
function renderFacts(){return `<div class="view">${renderHead('05 · chassis archive','Generations / fitment atlas','A visual reference for the four chassis families. Use the manual filter after choosing the car, not before.')}<div class="photo-grid">${generations.map(g=>`<article class="generation-card"><img src="${g.image}" alt="${g.id} generation Mazda MX-5 Miata"><div class="generation-copy"><span class="fitment-stamp">${g.id} · ${g.years}</span><h3>${g.engine}</h3><p>${esc(g.note)}</p><p><strong>Watch first:</strong> ${esc(g.watch[0])}</p><a href="${g.source}" target="_blank" rel="noreferrer">Photo: ${esc(g.imageCredit)} ↗</a><button class="button text small" data-action="generation-manual" data-generation="${g.id}">Open ${g.id} repair file →</button></div></article>`).join('')}</div><div class="section-band"><h2>Workshop manual architecture</h2><span class="eyebrow">${books.reduce((s,b)=>s+b.pages,0)} planned pages</span></div><div class="chapter-list">${books.map(chapterRow).join('')}</div></div>`}
function bind(){
  document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',handleAction));
  document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',handleField));
  document.querySelectorAll('[data-field="query"]').forEach(el=>el.addEventListener('input',e=>{state.query=e.target.value;renderManualOnly()}));
}
function handleField(e){const field=e.currentTarget.dataset.field;if(field.startsWith('dyno-')){const key=field.replace('dyno-','');state.dyno={...(state.dyno||{}),[key]:e.currentTarget.value};if(key==='weight'||key==='loss')state.dyno[key]=Number(state.dyno[key])||0;persistSilent();render();return}state[field]=e.currentTarget.value;if(field==='year'||field==='mileage'||field==='budget'||field==='taxRate')state[field]=Number(state[field])||0;if(field.startsWith('profile'))state.profile[field.replace('profile-','')]=e.currentTarget.value;persistSilent()}
function persistSilent(){store.save(state)}
function handleAction(e){const el=e.currentTarget;const action=el.dataset.action;
  if(action==='view'){setView(el.dataset.view);return}
  if(action==='edit-vehicle'){setView('garage');setTimeout(()=>$('#profile-name')?.focus(),0);return}
  if(action==='open-book'){state.activeBook=el.dataset.book;state.view='manual';state.query='';render();return}
  if(action==='clear-search'){state.query='';state.generationFilter='all';render();return}
  if(action==='filter-generation'){state.generationFilter=el.dataset.generation;state.activeBook='generation';state.view='manual';render();return}
  if(action==='generation-manual'){state.generationManual=el.dataset.generation;state.view='genmanual';render();return}
  if(action==='build-tab'){state.buildTab=el.dataset.tab||'estimate';render();return}
  if(action==='save-profile'){saveProfile();return}
  if(action==='save-procedure'){const id=el.dataset.id;state.savedProcedures=state.savedProcedures.includes(id)?state.savedProcedures.filter(x=>x!==id):[...state.savedProcedures,id];persist();return}
  if(action==='print'){window.print();return}
  if(action==='export'){exportState();return}
  if(action==='add-part'){addCatalogPart(el.dataset.part);return}
  if(action==='add-plan'){addPlanItem(el.dataset.part);return}
  if(action==='add-custom-plan'){addCustomPlan();return}
  if(action==='add-suggestion'){addSuggestion(el);return}
  if(action==='add-top-recommendation'){addTopRecommendation(el);return}
  if(action==='add-performance'){addPerformanceUpgrade(el.dataset.performance);return}
  if(action==='add-other-upgrade'){addOtherUpgrade();return}
  if(action==='toggle-dyno-upgrade'){toggleDynoUpgrade(el.dataset.upgrade);return}
  if(action==='remove-plan'){removePlan(el.dataset.id);return}
  if(action==='remove-part'){removePart(el.dataset.id);return}
  if(action==='save-plan'){state.budget=Number($('#budget-input')?.value)||0;state.planName=$('#plan-name')?.value||'Build plan';persist();return}
  if(action==='load-path'){loadPath(el.dataset.path);return}
  if(action==='load-street-option'){loadStreetOption(el.dataset.option);return}
  if(action==='add-history'){addHistory();return}
}
function renderManualOnly(){const main=$('.main');if(state.view==='manual'&&main){main.innerHTML=renderManual();bind()}}
function saveProfile(){state.profile={...state.profile,buildName:$('#profile-name')?.value||state.profile.buildName,market:$('#profile-market')?.value||state.profile.market,generation:$('#profile-generation')?.value||state.profile.generation,year:Number($('#profile-year')?.value)||state.profile.year,trim:$('#profile-trim')?.value||state.profile.trim,mileage:Number($('#profile-mileage')?.value)||state.profile.mileage};record('Vehicle','Updated vehicle record');persist()}
function addCatalogPart(id){const item=parts.find(p=>p.id===id);if(!item)return;if(!item.generations.includes(genKey())){toast(`${item.name} needs ${item.generations.join('/')} fitment review`);return}const prior=state.parts.find(p=>p.slot===item.slot);if(prior){record('Replaced',`${prior.part} replaced in ${prior.slot}`,0,`New part: ${item.name}`);state.parts=state.parts.filter(p=>p.id!==prior.id)}const part={id:Date.now(),category:item.category,slot:item.slot,part:item.name,cost:item.cost,date:new Date().toISOString().slice(0,10),notes:item.impact};state.parts.push(part);record('Installed',`${item.name} → ${item.slot}`,item.cost,item.impact);persist()}
function addPlanItem(id){const item=parts.find(p=>p.id===id);if(!item)return;if(!item.generations.includes(genKey())){toast(`${item.name} needs ${item.generations.join('/')} fitment review`);return}if(state.plan.some(x=>x.source===item.id)){toast('That part is already in the estimate');return}state.plan.push({id:Date.now()+Math.random(),source:item.id,name:item.name,category:item.category,generation:genKey(),cost:item.cost,done:false,notes:item.prereq});persist()}
function addCustomPlan(){const name=$('#custom-part-name')?.value?.trim();if(!name){toast('Name the part or service first');return}const cost=Number($('#custom-part-cost')?.value)||0;state.plan.push({id:Date.now()+Math.random(),source:null,name,category:'Custom',generation:genKey(),cost,done:false,notes:'Custom estimate · verify fitment and companion work'});persist()}
function addSuggestion(el){const name=el.dataset.name;if(!name)return;if(state.plan.some(x=>x.name===name)){toast('That recommendation is already estimated');return}state.plan.push({id:Date.now()+Math.random(),source:el.dataset.source||null,name,category:'Recommended companion',generation:genKey(),cost:Number(el.dataset.cost)||0,done:false,notes:el.dataset.notes||'Recommended companion item'});persist()}
function addTopRecommendation(el){const name=el.dataset.name;if(!name)return;if(state.plan.some(x=>x.name===name)){toast('That recommendation is already estimated');return}state.plan.push({id:Date.now()+Math.random(),source:null,name,category:'Top recommendation',generation:genKey(),cost:Number(el.dataset.cost)||0,done:false,notes:el.dataset.notes||'Editorial top recommendation · verify current price, fitment, shipping, and tax'});persist()}
function addPerformanceUpgrade(id){const item=performanceUpgradeOptions.find(x=>x.id===id);if(!item)return;if(!item.generations.includes(genKey())){toast(`${item.name} needs ${item.generations.join('/')} fitment review`);return}if(state.plan.some(x=>x.source===`performance:${item.id}`)){toast('That upgrade is already in the estimate');return}const first=Number((item.price.match(/[0-9,]+/)||['0'])[0].replace(/,/g,''));state.plan.push({id:Date.now()+Math.random(),source:`performance:${item.id}`,name:item.name,category:`Performance · ${item.category}`,generation:genKey(),cost:first,done:false,notes:`${item.requires} Product: ${item.url}`});state.planName=item.name;persist()}
function addOtherUpgrade(){const name=$('#other-upgrade-name')?.value?.trim();if(!name){toast('Name the Other upgrade first');return}const cost=Number($('#other-upgrade-cost')?.value)||0;const url=$('#other-upgrade-url')?.value?.trim();state.plan.push({id:Date.now()+Math.random(),source:`other:${Date.now()}`,name,category:'Performance · Other',generation:genKey(),cost,done:false,notes:`Custom part or service${url?` · ${url}`:''} · verify fitment and dependencies`});state.planName=name;record('Plan',`Added Other performance upgrade: ${name}`,cost,url||'Custom performance catalog entry');persist()}
function toggleDynoUpgrade(id){const current=state.dyno?.upgrades||[];state.dyno={...(state.dyno||{}),upgrades:current.includes(id)?current.filter(x=>x!==id):[...current,id]};persistSilent();render()}
function removePlan(id){state.plan=state.plan.filter(x=>String(x.id)!==String(id));persist()}
function removePart(id){const item=state.parts.find(p=>String(p.id)===String(id));if(!item)return;state.parts=state.parts.filter(p=>String(p.id)!==String(id));record('Archived',`${item.part} archived from ${item.slot}`);persist()}
function loadPath(id){const path=buildPaths.find(p=>p.id===id);if(!path)return;path.items.forEach(itemId=>{const item=parts.find(p=>p.id===itemId);if(item&&!state.plan.some(x=>x.source===item.id))state.plan.push({id:Date.now()+Math.random(),source:item.id,name:item.name,cost:item.cost,done:false})});state.planName=path.title;persist()}
function loadStreetOption(id){const option=streetBuildOptions.find(x=>x.id===id);if(!option)return;let added=0;option.items.forEach(itemId=>{const item=parts.find(p=>p.id===itemId);if(item&&!state.plan.some(x=>x.source===item.id)){state.plan.push({id:Date.now()+Math.random(),source:item.id,name:item.name,category:item.category,generation:genKey(),cost:item.cost,done:false,notes:item.prereq});added++}});state.planName=option.title;record('Plan',`Loaded street-build path: ${option.title}`,0,`${option.stage} · ${option.budget} · ${option.summary}`);persist();toast(added?`${option.title} loaded · ${added} starting items added`:`${option.title} selected · existing items kept`)}
function addHistory(){const type=$('#history-type')?.value||'Service';const description=$('#history-title')?.value?.trim();if(!description){toast('Add a short description first');return}record(type,description,Number($('#history-cost')?.value)||0,$('#history-notes')?.value||'');persist()}
function exportState(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`miata-bible-garage-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url);toast('Garage export downloaded')}
window.addEventListener('hashchange',()=>{const match=location.hash.match(/manual\/([^/]+)/);if(match){state.activeBook=match[1];state.view='manual';render()}});
render();
